      "text": "आप अपना नाम भी बता दीजिए please।"
    },
    {
      "i": 31,
      "speaker": "caller",
      "text": "मेरा नाम मोनू शर्मा है जी।"
    },
    {
      "i": 32,
      "speaker": "bot",
      "text": "ठीक है Monu जी आपको मैं seller details WhatsApp पे भेज दूंगी जिससे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 33,
      "speaker": "caller",
      "text": "एक।"
    },
    {
      "i": 34,
      "speaker": "caller",
      "text": "जी madam ऐसा है मेरे को ये बता दो क्योंकि मैं फिर जो अपने आप ही खुद मंगवा ले करूँगा घर ही बाल्टी आपके यहाँ से।"
    },
    {
      "i": 35,
      "speaker": "bot",
      "text": "जी मैं आपको अच्छे sellers से connect करने में मदद करूंगी बस details confirm हो गई है।"
    },
    {
      "i": 36,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 37,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    },
    {
      "i": 38,
      "speaker": "caller",
      "text": "ठीक है दे।"
    }
  ]
}
